            raise ValueError("LangWatch API key is required but not provided")

        headers = {
            **build_auth_headers(
                api_key=Client._api_key,
                project_id=Client._project_id,
            ),
            "X-LangWatch-SDK-Version": str(__version__),
        }

        if Client._debug:
